esqlQuery.esql:
FROM metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND (`metrics.storage.googleapis.com/storage/object_count` IS NOT NULL
         OR `metrics.storage.googleapis.com/storage/total_bytes` IS NOT NULL)
//
// --- Snapshot handling -------------------------------------------------------------------------
// Both metrics are point-in-time snapshots recomputed roughly once per day and re-reported on every
// poll. They must NEVER be summed over time. The correct shape is MAX per series within a narrow
// slice, then SUM across series. The 2-day head and tail slices always contain a daily snapshot.
// object_count and total_bytes do not reliably share a document, so each is aggregated
// independently and the ratio is taken afterwards — never with per-document EVAL arithmetic.
| STATS latest_class_objects   = MAX(`metrics.storage.googleapis.com/storage/object_count`) WHERE @timestamp >= NOW() - 2 days,
        earliest_class_objects = MAX(`metrics.storage.googleapis.com/storage/object_count`) WHERE @timestamp < NOW() - 12 days,
        latest_class_bytes     = MAX(`metrics.storage.googleapis.com/storage/total_bytes`)  WHERE @timestamp >= NOW() - 2 days,
        earliest_class_bytes   = MAX(`metrics.storage.googleapis.com/storage/total_bytes`)  WHERE @timestamp < NOW() - 12 days
    BY resource.attributes.bucket_name, attributes.storage_class
// A bucket can hold several classes at once, so sum the per-class snapshots into a bucket total.
| STATS latest_objects   = SUM(latest_class_objects),
        earliest_objects = SUM(earliest_class_objects),
        latest_bytes     = SUM(latest_class_bytes),
        earliest_bytes   = SUM(earliest_class_bytes),
        storage_classes  = VALUES(attributes.storage_class)
    BY resource.attributes.bucket_name
// Guard every denominator, and ignore buckets too small for operation costs to matter.
// 100,000 objects; raise it in estates where small buckets are normal and uninteresting.
| WHERE earliest_objects > 0 AND earliest_bytes > 0 AND latest_bytes > 0
    AND latest_objects >= 100000
// Cast before dividing: object_count is a long and `a / b` would be integer division.
| EVAL latest_avg_object_bytes   = latest_bytes / latest_objects,
       earliest_avg_object_bytes = earliest_bytes / earliest_objects
| EVAL object_growth_pct = ROUND((latest_objects - earliest_objects)::DOUBLE / earliest_objects * 100.0, 2),
       byte_growth_pct   = ROUND((latest_bytes - earliest_bytes) / earliest_bytes * 100.0, 2),
       avg_object_size_change_pct = ROUND((latest_avg_object_bytes - earliest_avg_object_bytes) / earliest_avg_object_bytes * 100.0, 2)
// Divergence test: materially more objects, each materially smaller. Both clauses are needed —
// average size alone would fire on a bucket that merely deleted its largest objects.
// Loosen to -15 / 10 to catch sprawl earlier, tighten for buckets that churn by design.
| WHERE object_growth_pct > 20.0 AND avg_object_size_change_pct < -25.0
| SORT avg_object_size_change_pct ASC
| LIMIT 50
